import {PRODUCTS,SIZES,COLORS,money,getProduct,escapeHtml as esc,prettyDate,dateStatus,datesFor,deliveryFor,unitPrice,bagTotals,sanitizeBag,filterProducts,recommend} from './shop.js';

const $=selector=>document.querySelector(selector);
const $$=selector=>[...document.querySelectorAll(selector)];
const BAG_KEY='petal-stem-bag-v1';
let storageAvailable=true;
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
let bag=sanitizeBag(readStorage(BAG_KEY,[]));
let currentProduct=null,verifiedDelivery=null,toastTimer;
let finder={step:0,occasion:'Just Because',style:'soft',budget:'65'};
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function saveStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;toast('Seu navegador não conseguiu salvar os dados. Suas escolhas ficarão disponíveis apenas nesta visita.');return false;}}
function saveBag(){saveStorage(BAG_KEY,bag);updateBagCount();}
function updateBagCount(){const count=bagTotals(bag).count;$('.bag-count').textContent=count;$('.bag-button').setAttribute('aria-label',`Abrir carrinho, ${count} ${count===1?'item':'itens'}`);}
function openDialog(id){$$('dialog[open]').forEach(d=>d.close());const dialog=$('#'+id);dialog.showModal();document.body.classList.add('modal-open');dialog.scrollTop=0;}
function closeDialog(dialog){dialog.close();document.body.classList.toggle('modal-open',$$('dialog[open]').length>0);}
$$('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>document.body.classList.toggle('modal-open',$$('dialog[open]').length>0));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog(dialog);}});});

function productCard(p){return `<article class="product-card"><a href="#bouquet/${p.id}" class="product-image-link" aria-label="Conheça ${p.name}, a partir de ${money(p.price)}"><img src="assets/${p.id}.webp" srcset="assets/${p.id}-small.webp 480w, assets/${p.id}.webp 1122w" sizes="(max-width:600px) 45vw, (max-width:800px) 44vw, 22vw" width="1122" height="1402" loading="lazy" alt="${p.alt}">${p.tag?`<span class="product-tag">${p.tag}</span>`:''}<span class="product-view-label" aria-hidden="true">↗</span></a><div class="product-card-header"><h3><a href="#bouquet/${p.id}">${p.name}</a></h3><span class="price">A partir de ${money(p.price)}</span></div><p class="product-description">${p.short}</p><div class="color-dots" role="img" aria-label="${p.palette}">${p.swatches.map(color=>`<span style="background:${color}"></span>`).join('')}</div></article>`;}
function renderCollection(){const values=Object.fromEntries(new FormData($('#filters')));const products=filterProducts(values);$('#product-grid').innerHTML=products.length?products.map(productCard).join(''):'<div class="no-results"><h3>Que tal outra combinação?</h3><p>Nenhum buquê corresponde a todos os filtros. Tente outro orçamento ou outra paleta.</p><button class="text-link" data-action="reset-filters">Ver todas as flores →</button></div>';const count=Object.values(values).filter(Boolean).length;$('#filter-count').textContent=count?` (${count})`:'';$('#collection-status').textContent=`${products.length} ${products.length===1?'buquê encontrado':'buquês encontrados'} com os filtros selecionados.`;}
function showFilters(show=true){$('#filters').hidden=!show;$('.filter-toggle').setAttribute('aria-expanded',String(show));}
function resetFilters(){$('#filters').reset();renderCollection();}
$('#filters').addEventListener('change',renderCollection);
$('#filters').addEventListener('reset',()=>setTimeout(renderCollection));

function dateOptions(product,selected=''){const options=datesFor(product);return `<option value="">Escolha uma data disponível</option>${selected&&!options.some(d=>d.date===selected)?`<option selected disabled value="${esc(selected)}">${esc(selected)} — atualize a data</option>`:''}${options.map(d=>`<option value="${d.date}" ${d.reason?'disabled':''} ${d.date===selected?'selected':''}>${prettyDate(d.date)}${d.reason?` — ${d.reason.includes('lotada')?'lotado':d.reason.includes('fecha')?'estúdio fechado':'indisponível'}`:''}</option>`).join('')}`;}
function renderProduct(p){currentProduct=p;verifiedDelivery=null;document.title=`${p.name} — Petal & Stem`;
$('#product-view').innerHTML=`<article class="product-page"><nav class="breadcrumbs" aria-label="Caminho de navegação"><a href="#home">Início</a><span>/</span><a href="#collection">Buquês da estação</a><span>/</span><span aria-current="page">${p.name}</span></nav><div class="product-layout"><div class="product-gallery"><img class="gallery-main" id="gallery-main" src="assets/${p.id}.webp" width="1122" height="1402" alt="${p.alt}"><div class="gallery-thumbs" role="group" aria-label="Fotos do buquê"><button data-photo="${p.id}" aria-label="Ver o buquê inteiro" aria-pressed="true"><img src="assets/${p.id}-small.webp" alt="" width="72" height="85"></button><button data-photo="${p.id}-detail" aria-label="Ver o buquê de cima" aria-pressed="false"><img src="assets/${p.id}-detail.webp" alt="" width="72" height="85"></button></div><p class="gallery-caption" id="gallery-caption">Tamanho Médio, embalado e pronto para presentear. Vaso não incluído.</p></div><div class="product-info"><p class="eyebrow">UM PEQUENO GESTO, CHEIO DE SIGNIFICADO</p><h1 tabindex="-1">${p.name}</h1><p class="product-lead">${p.description}</p><div class="product-price-row"><span class="product-price" id="product-price">${money(p.price+20)}</span><span>USD · Cartão escrito à mão incluído</span></div><dl class="product-specs"><dt>As flores</dt><dd>${p.varieties}</dd><dt>A paleta</dt><dd>${p.palette}</dd><dt>O tamanho</dt><dd id="product-dimensions">${SIZES.classic.dimensions}</dd></dl><p class="substitution-note">As variedades podem mudar conforme a estação e a disponibilidade. Preservamos a paleta, o tamanho e o estilo, com flores de valor igual ou superior. Fotos ilustrativas.</p><form id="purchase-form"><fieldset><legend>Escolha o tamanho</legend><div class="choice-grid size-grid">${Object.entries(SIZES).map(([key,size])=>`<label><input type="radio" name="size" value="${key}" ${key==='classic'?'checked':''}><span>${size.name} · ${money(p.price+size.extra)}<small>${size.stems}</small></span></label>`).join('')}</div><p id="size-description" class="size-description">${SIZES.classic.description}</p></fieldset><fieldset class="bouquet-colors"><legend>Escolha a cor</legend><div class="color-choices">${p.colors.map(key=>`<label><input type="radio" name="color" value="${key}" ${key==='original'?'checked':''}><span><i aria-hidden="true" style="background:${COLORS[key].swatch}"></i>${COLORS[key].name}</span></label>`).join('')}</div><p class="field-hint">${p.id==='sunflower'?'Os girassóis permanecem amarelos. A cor escolhida orienta as flores de apoio e a embalagem.':'A cor escolhida orienta a montagem do arranjo. As fotos mostram a paleta original.'}</p></fieldset><label class="gift-label" for="bouquet-description">Descreva o buquê que você imagina <span><span id="description-count">0</span>/1000</span></label><textarea id="bouquet-description" name="description" minlength="10" maxlength="1000" rows="4" required placeholder="Ex.: um buquê delicado, com flores claras, folhagens leves e embalagem em papel kraft." aria-describedby="description-help"></textarea><p id="description-help" class="field-hint">Conte como gostaria do arranjo: estilo, combinação de flores e embalagem. Obrigatório, de 10 a 1000 caracteres. A mensagem do cartão será preenchida abaixo.</p><div class="delivery-check"><label for="delivery-zip">Vamos conferir a entrega?</label><div class="zip-row"><input id="delivery-zip" name="zip" type="text" inputmode="numeric" autocomplete="postal-code" maxlength="5" pattern="[0-9]{5}" placeholder="Código postal (ZIP)" aria-describedby="delivery-status" required><button type="button" class="button" data-action="check-zip">Consultar ZIP</button></div><p id="delivery-status" class="delivery-status" role="status">Entrega demonstrativa em Portland · Tente 97201–97206.<br>Frete de US$ 6 a US$ 9 por buquê, informado antes de adicionar ao carrinho.</p></div><label class="field-label" for="delivery-date">Um belo dia para receber flores</label><select id="delivery-date" name="date" required disabled aria-describedby="date-help">${dateOptions(p)}</select><p id="date-help" class="field-hint">Consulte o código postal primeiro. ${p.lead} dias de antecedência · Terça a sábado · Das 9h às 18h. Datas no fuso de Portland.</p><label class="gift-label" for="gift-message">Suas palavras, escritas à mão <span><span id="message-count">0</span>/240</span></label><textarea id="gift-message" name="message" maxlength="240" rows="3" placeholder="Uma mensagem para alegrar o dia de alguém…" aria-describedby="gift-help"></textarea><p id="gift-help" class="field-hint">Opcional. Lembre de assinar seu nome. O cartão está incluído.</p><label class="add-vase"><input name="vase" type="checkbox"><span>Incluir um vaso de vidro · US$ 18<small>20 cm de altura × 12 cm de largura. Buquê pronto para colocar no vaso.</small></span></label><div class="purchase-total"><span>Buquê e adicionais</span><span id="purchase-subtotal">${money(p.price+20)}</span></div><div class="purchase-total"><span>Frete demonstrativo</span><span id="purchase-delivery">Consulte o ZIP acima</span></div><p id="purchase-error" class="error-text" role="alert" hidden></p><button id="add-to-bag" class="button full-width" type="submit" disabled><span id="add-label">Consulte a entrega para adicionar ao carrinho</span><span aria-hidden="true">↗</span></button><p class="purchase-note">Loja demonstrativa · Nenhum pagamento é cobrado. O carrinho fica salvo neste navegador.</p></form><div class="faq-list"><details><summary>O que chega na entrega?<span aria-hidden="true">+</span></summary><p>Um buquê preparado à mão, envolto em papel de seda e kraft, com instruções de cuidado e seu cartão escrito à mão. As fotos mostram o tamanho Médio. O vaso de vidro só está incluído quando selecionado. Os vasos decorativos do estúdio não fazem parte do produto.</p></details><details><summary>Um pouco de cuidado faz a diferença<span aria-hidden="true">+</span></summary><p>Corte de 1 a 2 cm de cada haste e coloque as flores em um vaso limpo com água fresca. Retire as folhas submersas e troque a água a cada dois dias. Evite calor e sol direto. As flores são decorativas, não comestíveis; mantenha longe dos animais de estimação.</p></details><details><summary>Entrega e substituições da estação<span aria-hidden="true">+</span></summary><p>A janela demonstrativa de entrega é das 9h às 18h, de terça a sábado. O frete é cobrado por buquê, mesmo quando o endereço é o mesmo. As substituições preservam a paleta, o tamanho e o valor. Estoque, capacidade de entrega e pagamentos reais ainda não estão integrados.</p></details></div></div></div><section class="related-products" aria-labelledby="related-title"><p class="eyebrow">MAIS ALGUMAS POSSIBILIDADES ENCANTADORAS</p><h2 id="related-title">Um sentimento para cada pessoa.</h2><div class="product-grid">${PRODUCTS.filter(other=>other.id!==p.id).map(productCard).join('')}</div></section></article>`;
$('#purchase-form').addEventListener('submit',addToBag);
$('#purchase-form').addEventListener('change',updatePurchase);
$('#delivery-zip').addEventListener('input',()=>{verifiedDelivery=null;$('#delivery-date').disabled=true;$('#delivery-status').className='delivery-status';$('#delivery-status').textContent='Consulte este código postal para ver o frete demonstrativo e as datas disponíveis.';updatePurchase();});
$('#delivery-zip').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();checkZip();}});
$('#bouquet-description').addEventListener('input',()=>{$('#description-count').textContent=$('#bouquet-description').value.length;updatePurchase();});
$('#gift-message').addEventListener('input',()=>$('#message-count').textContent=$('#gift-message').value.length);
}
function checkZip(){const result=deliveryFor($('#delivery-zip').value);verifiedDelivery=result.ok?result:null;$('#delivery-status').textContent=result.message;$('#delivery-status').className=`delivery-status ${result.ok?'success':'error'}`;$('#delivery-zip').setAttribute('aria-invalid',String(!result.ok));$('#delivery-date').disabled=!result.ok;updatePurchase();if(result.ok)$('#delivery-date').focus();}
function selectedPurchase(){const values=new FormData($('#purchase-form'));return {product:currentProduct.id,size:values.get('size'),vase:values.get('vase')==='on',zip:$('#delivery-zip').value.trim(),date:values.get('date')||'',message:values.get('message').trim(),color:values.get('color')||'original',description:String(values.get('description')||'').trim(),quantity:1};}
function updatePurchase(){if(!$('#purchase-form'))return;const item=selectedPurchase(),size=SIZES[item.size],price=unitPrice(item);$('#product-price').textContent=money(price);$('#product-dimensions').textContent=size.dimensions;$('#size-description').textContent=size.description;$('#purchase-subtotal').textContent=money(price);$('#purchase-delivery').textContent=verifiedDelivery?money(verifiedDelivery.fee):'Consulte o ZIP acima';const error=item.date?dateStatus(item.date,currentProduct):'';$('#purchase-error').textContent=error;$('#purchase-error').hidden=!error;const valid=verifiedDelivery&&verifiedDelivery.zip===item.zip&&item.date&&!error&&item.description.length>=10&&currentProduct.colors.includes(item.color);$('#add-to-bag').disabled=!valid;$('#add-label').textContent=!verifiedDelivery?'Consulte a entrega para adicionar ao carrinho':!item.date?'Escolha uma data de entrega':error?'Escolha outra data de entrega':item.description.length<10?'Descreva o buquê para continuar':`Adicionar ao carrinho · ${money(price+verifiedDelivery.fee)}`;}
function addToBag(event){event.preventDefault();const item=selectedPurchase();if(!verifiedDelivery||verifiedDelivery.zip!==item.zip||!deliveryFor(item.zip).ok||dateStatus(item.date,currentProduct)||item.description.length<10||!currentProduct.colors.includes(item.color)){updatePurchase();return;}const existing=bag.find(i=>i.product===item.product&&i.size===item.size&&i.vase===item.vase&&i.zip===item.zip&&i.date===item.date&&i.message===item.message&&(i.color||'original')===item.color&&(i.description||'')===item.description);if(existing?.quantity===9){toast('Você já tem 9 unidades deste arranjo no carrinho, o limite demonstrativo.');return;}if(bag.length>=30&&!existing){toast('Seu carrinho demonstrativo está cheio. Remova um item antes de adicionar outro.');return;}if(existing)existing.quantity++;else bag.push({...item,id:crypto.randomUUID()});saveBag();renderBag();openDialog('bag-dialog');toast(`${currentProduct.name} está no seu carrinho.`);}

function renderBag(){if(!bag.length){$('#bag-content').innerHTML='<div class="empty-bag"><span aria-hidden="true">✳</span><h3>Espaço para algo especial.</h3><p>Seu carrinho está esperando um pouco de cor.</p><a class="button" data-close href="#collection">Encontre suas flores <span aria-hidden="true">↗</span></a></div>';return;}
const totals=bagTotals(bag),invalid=bag.some(item=>dateStatus(item.date,getProduct(item.product)));
$('#bag-content').innerHTML=bag.map(item=>{const p=getProduct(item.product),error=dateStatus(item.date,p);return `<article class="bag-item" data-item="${esc(item.id)}"><div class="bag-item-main"><a href="#bouquet/${p.id}" data-close aria-label="Ver ${p.name}"><img src="assets/${p.id}-small.webp" alt="${p.alt}" width="90" height="115"></a><div><h3>${p.name}</h3><p>${SIZES[item.size].name}${item.vase?' · com vaso de vidro':''}</p><p class="bag-personalization">Cor: ${COLORS[item.color||'original'].name}${item.description?`<br><strong>Seu arranjo:</strong> ${esc(item.description)}`:''}</p><p>ZIP ${item.zip} · ${money(deliveryFor(item.zip).fee)} de frete por unidade</p><div class="quantity-control"><button data-bag-command="decrease" aria-label="Diminuir quantidade de ${p.name}" ${item.quantity<=1?'disabled':''}>−</button><output aria-label="Quantidade">${item.quantity}</output><button data-bag-command="increase" aria-label="Aumentar quantidade de ${p.name}" ${item.quantity>=9?'disabled':''}>+</button></div></div><div class="bag-item-price">${money(unitPrice(item)*item.quantity)}<button class="remove-item" data-bag-command="remove" aria-label="Remover ${p.name}">Remover</button></div></div><label class="field-label" style="margin-top:16px" for="date-${esc(item.id)}">Data de entrega</label><select id="date-${esc(item.id)}" data-bag-date aria-describedby="bag-date-status-${esc(item.id)}">${dateOptions(p,item.date)}</select><p class="${error?'error-text':'field-hint'}" id="bag-date-status-${esc(item.id)}">${error||'Janela demonstrativa de entrega: das 9h às 18h'}</p><details class="bag-message"><summary>${item.message?'Editar mensagem do presente':'Adicionar mensagem ao presente'}</summary><label class="sr-only" for="message-${esc(item.id)}">Mensagem do presente para ${p.name}</label><textarea id="message-${esc(item.id)}" maxlength="240" rows="3">${esc(item.message)}</textarea><button class="text-link" data-bag-command="message">Salvar mensagem <span aria-hidden="true">→</span></button></details></article>`;}).join('')+`<div class="bag-totals"><div><span>Buquês e adicionais</span><span>${money(totals.subtotal)}</span></div><div><span>Frete demonstrativo · por buquê</span><span>${money(totals.delivery)}</span></div><div><span>Estimativa demonstrativa de impostos</span><span>US$ 0</span></div><div class="grand-total"><span>Total demonstrativo</span><span>${money(totals.total)}</span></div>${invalid?'<p class="notice error">Uma data de entrega salva não está mais disponível. Escolha uma nova data acima para revisar o carrinho.</p>':''}<button class="button full-width" data-action="review" ${invalid?'disabled':''}>Revisar carrinho demonstrativo <span aria-hidden="true">↗</span></button><p class="fine-print">Pagamento, entrega real e cálculo final de impostos não estão integrados. Não é possível fazer um pedido nesta página. ${storageAvailable?'Seu carrinho fica salvo neste navegador.':'O armazenamento do navegador está indisponível; seu carrinho fica disponível apenas nesta visita.'}</p></div>`;
}
function bagCommand(button){const element=button.closest('[data-item]'),item=bag.find(i=>i.id===element.dataset.item);if(!item)return;const command=button.dataset.bagCommand;
if(command==='message'){item.message=element.querySelector('textarea').value.slice(0,240);saveBag();element.querySelector('summary').textContent=item.message?'Editar mensagem do presente':'Adicionar mensagem ao presente';element.querySelector('details').open=false;element.querySelector('summary').focus();toast('Sua mensagem foi salva.');return;}
if(command==='remove'){bag=bag.filter(i=>i.id!==item.id);toast(`${getProduct(item.product).name} foi removido do carrinho.`);}else item.quantity=Math.max(1,Math.min(9,item.quantity+(command==='increase'?1:-1)));
saveBag();renderBag();const newButton=$(`[data-item="${item.id}"] [data-bag-command="${command}"]`);if(newButton&&!newButton.disabled)newButton.focus();else $('#bag-dialog .close-button').focus();}
$('#bag-content').addEventListener('change',event=>{if(event.target.matches('[data-bag-date]')){const item=bag.find(i=>i.id===event.target.closest('[data-item]').dataset.item);if(!item)return;item.date=event.target.value;saveBag();renderBag();$(`#date-${item.id}`)?.focus();}});
function reviewBag(){const invalid=bag.some(item=>dateStatus(item.date,getProduct(item.product)));if(!bag.length||invalid){renderBag();return;}const totals=bagTotals(bag);$('#info-content').innerHTML=`<h2 id="info-title">Uma bela escolha.<br>Por enquanto, uma demonstração.</h2><p>Esta é uma prévia do carrinho. Pagamentos e serviços reais de entrega não estão integrados; nenhum pedido será criado.</p><ul class="review-list">${bag.map(item=>`<li><strong>${item.quantity} × ${getProduct(item.product).name}</strong>${SIZES[item.size].name}${item.vase?' + vaso de vidro':''}<br>Cor: ${COLORS[item.color||'original'].name}${item.description?`<br>Seu arranjo: ${esc(item.description)}`:''}<br>${prettyDate(item.date)} · ZIP ${item.zip}${item.message?`<br>Mensagem do cartão: “${esc(item.message)}”`:''}</li>`).join('')}</ul><div class="soft-panel"><strong>Total demonstrativo: ${money(totals.total)}</strong>Inclui ${money(totals.delivery)} de frete ilustrativo e US$ 0 de impostos demonstrativos. Preços e disponibilidade devem ser confirmados antes de uma compra real.</div><p>Nenhum dado de pagamento foi solicitado. Nenhum pedido foi feito ou confirmado. A compra sem cadastro poderá ser oferecida quando um serviço de pagamento for integrado.</p><button class="button full-width" data-action="bag">Voltar ao carrinho <span aria-hidden="true">→</span></button>`;openDialog('info-dialog');}

const occasionLabels={'Happy Birthday':'Feliz aniversário','Thank You':'Muito obrigado','Thinking of You':'Lembrei de você','Congratulations':'Parabéns pela conquista','Just Because':'Só porque sim'};
const frequencyLabels={Weekly:'semanais',Fortnightly:'quinzenais',Monthly:'mensais'};
const finderSteps=[{key:'occasion',title:'Qual é a ocasião?',copy:'Grandes momentos, pequenos gestos. Todos merecem flores.',choices:['Happy Birthday','Thank You','Thinking of You','Congratulations','Just Because']},{key:'style',title:'Qual estilo combina com a pessoa?',copy:'Uma paleta, uma personalidade e um pouco de intuição.',choices:[['soft','Suave e delicado'],['bright','Vibrante e alegre'],['wild','Livre e surpreendente']]},{key:'budget',title:'Qual orçamento fica bom para você?',copy:'Preços dos buquês sem vaso ou frete. O frete demonstrativo acrescenta de US$ 6 a US$ 9 por buquê.',choices:[['50','Até US$ 50'],['65','Até US$ 65'],['80','Até US$ 80']]}];
function renderFinder(){const content=$('#finder-content');if(finder.step===3){const results=recommend(finder);content.innerHTML=`<p class="eyebrow">UM POUCO DE INTUIÇÃO FLORAL</p><h2 id="finder-title">Estas flores combinam com você.</h2><p>Estas são as opções que mais combinam com a ocasião e o estilo, dentro do orçamento de ${money(Number(finder.budget))}. Os preços abaixo são do tamanho Pequeno, sem frete.</p>${results.map(p=>`<div class="finder-result"><img src="assets/${p.id}-small.webp" alt="${p.alt}" width="140" height="175"><div><h3>${p.name}</h3><p>${p.short}<br>A partir de ${money(p.price)} · ${p.palette}</p><a class="text-link" data-close href="#bouquet/${p.id}">Conheça seu buquê <span aria-hidden="true">↗</span></a></div></div>`).join('')}<button class="text-link" data-action="finder-restart">Começar de novo <span aria-hidden="true">↻</span></button>`;return;}
const step=finderSteps[finder.step];content.innerHTML=`<div class="finder-progress" role="img" aria-label="Etapa ${finder.step+1} de 3">${[0,1,2].map(i=>`<span class="${i<=finder.step?'active':''}"></span>`).join('')}</div><p class="eyebrow">ETAPA ${finder.step+1} DE 3</p><h2 id="finder-title">${step.title}</h2><p>${step.copy}</p><form id="finder-form"><fieldset><legend class="sr-only">${step.title}</legend><div class="choice-grid">${step.choices.map(choice=>{const [value,label]=Array.isArray(choice)?choice:[choice,occasionLabels[choice]||choice];return `<label><input name="answer" type="radio" value="${value}" ${finder[step.key]===value?'checked':''} required><span>${label}</span></label>`;}).join('')}</div></fieldset><div class="finder-actions">${finder.step?'<button type="button" class="text-link" data-action="finder-back">← Voltar</button>':'<span></span>'}<button class="button" type="submit">${finder.step===2?'Encontrar minhas flores':'Continuar'} <span aria-hidden="true">→</span></button></div></form>`;
$('#finder-form').addEventListener('submit',event=>{event.preventDefault();finder[step.key]=new FormData(event.target).get('answer');finder.step++;renderFinder();focusFinder();});}
function focusFinder(){$('#finder-title').setAttribute('tabindex','-1');$('#finder-title').focus();}
function openFinder(){finder.step=0;renderFinder();openDialog('finder-dialog');}

const policies={care:{title:'Um pouco de cuidado. Mais dias bonitos.',copy:'Retire a embalagem assim que o buquê chegar. Corte de 1 a 2 cm das hastes na diagonal e coloque as flores em um vaso limpo com água fresca. Retire as folhas submersas, troque a água a cada dois dias e apare as hastes quando necessário. Evite sol direto, fontes de calor e frutas maduras. Remova flores murchas para conservar o restante do buquê. As flores são decorativas, não comestíveis; mantenha fora do alcance de animais e crianças pequenas.'},returns:{title:'Cada flor escolhida com carinho.',copy:'Política demonstrativa: as substituições da estação preservariam a paleta, o formato e o valor do buquê. Fotos ilustrativas. Em uma futura loja real, arranjos danificados ou incorretos devem ser informados ao estúdio, com fotos, em até 24 horas após a entrega, para avaliar a troca ou o reembolso. As condições reais precisam ser confirmadas antes do lançamento. Este protótipo não processa vendas ou devoluções reais.'},privacy:{title:'Seus momentos continuam sendo seus.',copy:'O carrinho, as mensagens de presente e as preferências de assinatura da loja ficam no armazenamento deste navegador. Ao criar uma conta, seu nome, e-mail e o hash da senha são salvos no banco local do projeto. A sessão usa um cookie protegido e os pedidos criados pela página de pedidos ficam vinculados à sua conta. Senhas em texto puro não são armazenadas. Este protótipo não solicita dados de pagamento ou endereço completo e não envia mensagens ao estúdio. Não há rastreamento de anúncios. Você pode limpar os dados do navegador para remover o carrinho e sair da conta para encerrar a sessão.'},terms:{title:'Transparência em cada detalhe.',copy:'A Petal & Stem é uma floricultura fictícia e esta loja é um protótipo interativo. Produtos, preços, disponibilidade, áreas de entrega, horários e contatos são ilustrativos. Os preços são exemplos em dólares americanos. As imagens florais foram criadas para este projeto. Nesta loja não é possível fazer pedidos, iniciar assinaturas ou pagar. Salvar um carrinho ou plano não reserva flores, confirma entregas ou realiza uma compra. Pagamentos, estoque, impostos, atendimento e entregas reais precisam ser integrados antes do lançamento.'}};
function showPolicy(key){const policy=policies[key];if(!policy)return;$('#info-content').innerHTML=`<h2 id="info-title">${policy.title}</h2><p>${policy.copy}</p><button class="button" data-close>Voltar às flores <span aria-hidden="true">↗</span></button>`;openDialog('info-dialog');}

function updateSubscription(){const values=new FormData($('#subscription-form')),price=values.get('plan')==='classic'?58:42;$('#subscription-summary').innerHTML=`<strong>Flores ${frequencyLabels[values.get('frequency')]} · ${money(price)} por entrega</strong>${values.get('plan')==='classic'?'20–25':'12–15'} hastes da estação, escolhidas pela equipe.<br>Com frete local demonstrativo: de ${money(price+6)} a ${money(price+9)} por entrega.<br>Área demonstrativa: códigos postais 97201–97206 de Portland. Vaso não incluído.`;}
$('#subscription-form').addEventListener('change',updateSubscription);
$('#subscription-form').addEventListener('submit',event=>{event.preventDefault();const plan=Object.fromEntries(new FormData(event.target));const saved=saveStorage('petal-stem-plan-v1',plan);toast(saved?'Seu plano demonstrativo foi salvo. Nenhuma assinatura foi iniciada.':'Seu plano demonstrativo fica disponível apenas nesta visita.');closeDialog($('#subscription-dialog'));});
function openSubscription(){const saved=readStorage('petal-stem-plan-v1',{});if(['Weekly','Fortnightly','Monthly'].includes(saved.frequency))$(`#subscription-form [name="frequency"][value="${saved.frequency}"]`).checked=true;if(['petite','classic'].includes(saved.plan))$(`#subscription-form [name="plan"][value="${saved.plan}"]`).checked=true;updateSubscription();openDialog('subscription-dialog');}

function route(initial=false){let hash;try{hash=decodeURIComponent(location.hash.slice(1)||'home');}catch{hash='home';}const productId=hash.startsWith('bouquet/')?hash.slice(8):null;$$('dialog[open]').forEach(closeDialog);$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Abrir menu');if(productId){const p=getProduct(productId);$('#home-view').hidden=true;$('#product-view').hidden=false;if(p){renderProduct(p);window.scrollTo({top:0,behavior:'instant'});if(!initial)$('#product-view h1').focus({preventScroll:true});}else{$('#product-view').innerHTML='<div class="section-wrap"><h1>Esse buquê não foi encontrado.</h1><p>Não encontramos este buquê. Há lindas opções esperando por você na coleção.</p><a class="button" href="#collection">Ver as flores →</a></div>';document.title='Buquê não encontrado — Petal & Stem';}return;}
currentProduct=null;$('#home-view').hidden=false;$('#product-view').hidden=true;document.title='Petal & Stem — Flores com sentimento.';if(hash==='home'){window.scrollTo({top:0,behavior:'instant'});}else{const target=document.getElementById(hash);if(target){if(target.tagName==='DETAILS')target.open=true;requestAnimationFrame(()=>target.scrollIntoView({behavior:initial?'instant':'smooth',block:'start'}));}}
}
window.addEventListener('hashchange',()=>route());
document.addEventListener('click',event=>{const close=event.target.closest('[data-close]');if(close)closeDialog(close.closest('dialog'));const photo=event.target.closest('[data-photo]');if(photo){$('#gallery-main').src=`assets/${photo.dataset.photo}.webp`;$('#gallery-main').alt=photo.dataset.photo.endsWith('-detail')?`Vista de cima de ${currentProduct.name} sobre a bancada do estúdio, mostrando as flores e a embalagem de papel`:currentProduct.alt;$$('[data-photo]').forEach(button=>button.setAttribute('aria-pressed',String(button===photo)));$('#gallery-caption').textContent=photo.dataset.photo.endsWith('-detail')?'Detalhes do buquê Médio. Cada arranjo é único.':'Tamanho Médio, embalado e pronto para presentear. Vaso não incluído.';}
const occasion=event.target.closest('[data-occasion]');if(occasion){resetFilters();$('#filters [name="occasion"]').value=occasion.dataset.occasion;showFilters();renderCollection();location.hash='collection';}
const policy=event.target.closest('[data-policy]');if(policy)showPolicy(policy.dataset.policy);
const bagButton=event.target.closest('[data-bag-command]');if(bagButton)bagCommand(bagButton);
const button=event.target.closest('[data-action]');if(!button)return;switch(button.dataset.action){case'bag':renderBag();openDialog('bag-dialog');break;case'menu':{const open=$('#mobile-nav').hidden;$('#mobile-nav').hidden=!open;button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');break;}case'filters':showFilters($('#filters').hidden);break;case'all-flowers':resetFilters();showFilters();$('#collection').scrollIntoView({behavior:'smooth'});break;case'reset-filters':resetFilters();break;case'finder':openFinder();break;case'finder-restart':finder.step=0;renderFinder();focusFinder();break;case'finder-back':finder.step=Math.max(0,finder.step-1);renderFinder();focusFinder();break;case'check-zip':checkZip();break;case'review':reviewBag();break;case'subscription':openSubscription();break;}
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#mobile-nav').hidden){$('#mobile-nav').hidden=true;$('.menu-button').setAttribute('aria-expanded','false');$('.menu-button').setAttribute('aria-label','Abrir menu');$('.menu-button').focus();}});
window.addEventListener('storage',event=>{if(event.key===BAG_KEY){bag=sanitizeBag(readStorage(BAG_KEY,[]));updateBagCount();if($('#bag-dialog').open)renderBag();}});
$('#copyright-year').textContent=new Date().getFullYear();
renderCollection();updateBagCount();route(true);
